function graduateSelection(recipe,forceAuto=false){
 const chosen=[],used=new Set(),roster=state.roster,sourceStar=recipe.star-1;
 const manual=!forceAuto&&graduateManualIds[recipe.key];
 if(manual){
  const valid=manual.every((pid,i)=>{const h=roster.find(g=>g.partner_id===pid);if(!h||state.acquisition?.exchange?.partner_id===pid)return false;if(i===0)return h.table_id===recipe.source&&h.stars===sourceStar;if(h.flags?.some(Boolean))return false;const need=recipe.material[i-1],star=Math.floor(need/10000),group=need%10000===9999?0:Math.floor(need/1000)%10;return need%1000===999?h.stars===star&&(!group||h.group===group):h.table_id===need&&h.stars===(recipe.local?recipe.base_star:girlsCatalog.find(g=>g.id===need)?.stars);});
  return {chosen:manual,missing:valid&&new Set(manual).size===manual.length?'':"Check your selection: Girls must be different and meet the recipe requirements."};
 }
 const pick=test=>{const hero=roster.find(h=>!used.has(h.partner_id)&&(!chosen.length||!h.flags?.some(Boolean))&&state.acquisition?.exchange?.partner_id!==h.partner_id&&test(h));if(hero){used.add(hero.partner_id);chosen.push(hero.partner_id);}return hero;};
 if(!pick(h=>h.table_id===recipe.source&&h.stars===sourceStar))return {chosen,missing:"You need a base Girl of "+sourceStar+'★.'};
 let missing='';
 for(const [i,need] of recipe.material.entries()){
  const star=Math.floor(need/10000),group=need%10000===9999?0:Math.floor(need/1000)%10;
  if(!forceAuto&&!$('graduate-auto').checked&&need%1000===999&&star===5){chosen[i+1]=0;missing="Choose 5★ materials manually or enable auto-selection.";continue;}
  const valid=h=>need%1000===999?h.stars===star&&(!group||girlsCatalog.find(g=>g.id===h.table_id)?.group===group):h.table_id===need&&h.stars===(recipe.local?recipe.base_star:girlsCatalog.find(g=>g.id===need)?.stars);
  const hero=roster.find(h=>!used.has(h.partner_id)&&!h.flags?.some(Boolean)&&state.acquisition?.exchange?.partner_id!==h.partner_id&&valid(h));
  chosen[i+1]=hero?.partner_id||0;if(hero)used.add(hero.partner_id);else missing="Missing materials of "+star+'★'+(group?" of "+(factionNames[group]||group):'')+'.';
 }
 return {chosen,missing};
}
