function makeHex(stage){
 const hex=node('button','stage-hex'+(stage.cleared?' done':'')+(stage.id===selectedStage?' selected':'')+(!stage.unlocked?' locked':''));
 hex.type='button';hex.disabled=busy||!stage.unlocked;
 if(stage.map&&battleMapIds.has(stage.map)){hex.classList.add('has-map');hex.style.setProperty('--stage-map-image',`url('/assets/battle-maps/${stage.map}.png')`);}
 hex.setAttribute('aria-label',"Stage "+stage.id+(stage.unlocked?'':" locked"));
 hex.setAttribute('aria-pressed',String(stage.id===selectedStage));
 const iconWrap=node('span','stage-hex-icon');
 if(!stage.unlocked){const img=node('img');img.src='/assets/stage-lock.png';img.alt='';iconWrap.append(img);}
 else if(stage.cleared){const img=node('img');img.src='/assets/stage-check.png';img.alt='';iconWrap.append(img);}
 else iconWrap.textContent='⚔';
 hex.append(iconWrap);
 hex.append(node('span','stage-hex-label',String(stage.chapter_stage!=null?stage.chapter_stage:stage.id)));
 hex.addEventListener('click',()=>{selectedStage=stage.id;render();});
 return hex;
}
function renderStageMap(){
 const wrap=$('stage-map');wrap.replaceChildren();
 const selected=state.stages.find(stage=>stage.id===selectedStage);
 const mapBg=selected?.map&&battleMapIds.has(selected.map)?selected.map:'battle_map_26_1';
 wrap.style.backgroundImage=`linear-gradient(#1b293bd9,#101a2bd9),url('/assets/battle-maps/${mapBg}.png')`;
 const perRow=5;
 const current=state.stages.find(s=>s.id===selectedStage),chapter=current?.chapter||1;
 const chapters=new Map([[chapter,state.stages.filter(stage=>Number(stage.chapter||1)===Number(chapter))]]);
 for(const[chapter,group]of chapters){
  const block=node('div','stage-chapter-block');
  block.append(node('span','stage-chapter-label',"Chapter "+chapter));
  const path=node('div','stage-chapter-path');
  for(let r=0;r*perRow<group.length;r++){
   const rowStages=group.slice(r*perRow,r*perRow+perRow),reversed=r%2===1;
   const subrow=node('div','stage-chapter-subrow'+(reversed?' reverse':''));
   rowStages.forEach((stage,i)=>{
    if(i>0)subrow.append(node('span','stage-link'));
    subrow.append(makeHex(stage));
   });
   path.append(subrow);
   if((r+1)*perRow<group.length)path.append(node('span','stage-turn'+(reversed?' turn-left':' turn-right')));
  }
  block.append(path);wrap.append(block);
 }
}
