 if(dailyQuizType===0){categoryPanel.replaceChildren();for(const category of event.categories){const button=node('button','daily-quiz-category');button.type='button';button.style.backgroundImage=`url('/assets/daily-quiz/${category.art}.png')`;const text=node('span');const tier=category.tiers.findLast?category.tiers.findLast(t=>state.level>=t.level):[...category.tiers].reverse().find(t=>state.level>=t.level);text.append(node('strong','',category.name),node('small','',state.developer?"Unlimited attempts":`${category.limit-category.used}/${category.limit} attempts today`),node('em','',tier?`Difficulty ${tier.difficulty} disponible`:`Unlocks at level ${category.tiers[0].level}`));button.append(text);button.addEventListener('click',()=>{dailyQuizType=category.type;dailyQuizResult=null;renderDailyQuiz();});categoryPanel.append(button);}return;}
